package piglatin

import "strings"

// Sentence translates an English sentence to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

// word translates a single word to Pig Latin.
func word(w string) string {
	// Rule 1: word begins with a vowel, or starts with "xr" or "yt".
	if isVowel(w[0]) || strings.HasPrefix(w, "xr") || strings.HasPrefix(w, "yt") {
		return w + "ay"
	}

	// Rules 2-4: find where the leading consonant cluster ends.
	i := 0
	for i < len(w) {
		switch c := w[i]; {
		case isVowel(c):
			// Rule 3: the "u" in "qu" counts as a consonant, so keep
			// moving past it together with the "q".
			if c == 'u' && i > 0 && w[i-1] == 'q' {
				i += 2
				continue
			}
			return w[i:] + w[:i] + "ay"
		case c == 'y' && i > 0:
			// Rule 4: "y" following consonants counts as a vowel.
			return w[i:] + w[:i] + "ay"
		}
		i++
	}
	return w + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

